mkdir -p /tmp/helper && cd /tmp/helper && cat > main.go <<'EOF'
package main

import (
	"crypto/ecdh"
	"crypto/rand"
	"fmt"
	"os"
)

// bech32 from BIP-173
var charset = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"

func polymod(values []byte) uint32 {
	chk := uint32(1)
	gen := []uint32{0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3}
	for _, v := range values {
		b := chk >> 25
		chk = (chk&0x1ffffff)<<5 ^ uint32(v)
		for i := 0; i < 5; i++ {
			if (b>>uint(i))&1 == 1 {
				chk ^= gen[i]
			}
		}
	}
	return chk
}

func hrpExpand(hrp string) []byte {
	ret := []byte{}
	for i := 0; i < len(hrp); i++ {
		ret = append(ret, hrp[i]>>5)
	}
	ret = append(ret, 0)
	for i := 0; i < len(hrp); i++ {
		ret = append(ret, hrp[i]&31)
	}
	return ret
}

func convertbits(data []byte, frombits, tobits uint, pad bool) []byte {
	acc := 0
	bits := uint(0)
	ret := []byte{}
	maxv := (1 << tobits) - 1
	for _, value := range data {
		acc = (acc << frombits) | int(value)
		bits += frombits
		for bits >= tobits {
			bits -= tobits
			ret = append(ret, byte((acc>>bits)&maxv))
		}
	}
	if pad && bits > 0 {
		ret = append(ret, byte((acc<<(tobits-bits))&maxv))
	}
	return ret
}

func encode(hrp string, data []byte) string {
	values := convertbits(data, 8, 5, true)
	combined := append(hrpExpand(hrp), values...)
	combined = append(combined, 0, 0, 0, 0, 0, 0)
	mod := polymod(combined) ^ 1
	ret := hrp + "1"
	for _, p := range values {
		ret += string(charset[p])
	}
	for i := 0; i < 6; i++ {
		ret += string(charset[(mod>>uint(5*(5-i)))&31])
	}
	return ret
}

func main() {
	curve := ecdh.X25519()
	var priv *ecdh.PrivateKey
	var err error
	if len(os.Args) > 1 && os.Args[1] == "-fixed" {
		b := make([]byte, 32)
		for i := range b {
			b[i] = byte(i + 1)
		}
		priv, err = curve.NewPrivateKey(b)
	} else {
		priv, err = curve.GenerateKey(rand.Reader)
	}
	if err != nil {
		panic(err)
	}
	fmt.Println("# public key:", encode("age", priv.PublicKey().Bytes()))
	fmt.Println(encode("age-secret-key-", priv.Bytes()))
}
EOF
go mod init helper >/dev/null 2>&1; go run . -fixed > /tmp/probe/key.txt; cat /tmp/probe/key.txt

cd /tmp/probe
E=/workspace/executable
R=age1q73he0q5yzfu3d64msd3p6rvksnrwjk3d2598mgtmlqt9wrdr37q2vrn72
$E -d -i key2.txt h2.age; echo "exit=$?"
echo ===
echo garbage | $E -d; echo "exit=$?"
echo ===
printf 'age-encryption.org/v1\n' | $E -d; echo "exit=$?"
echo ===
printf 'not an age file at all, longer content here' | $E -d; echo "exit=$?"
echo ===
# truncated payload
head -c 150 h2.age | $E -d -i key.txt; echo "exit=$?"
echo ===
# corrupted MAC
sed '3s/.$/A/' h2.age | $E -d -i key.txt 2>&1 | head -3; echo
echo ===
$E -d -i nonexistent.txt h2.age; echo "exit=$?"

